        for (int i = 0; i < numCourses; i++) if (color[i] == 0 && !dfs(i)) return new int[0];
        int[] order = new int[numCourses];
        for (int i = 0; i < numCourses; i++) order[i] = post.get(numCourses - 1 - i);
        return order;
    }

