    def findMinHeightTrees(self, n: int, edges: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        def height(root):
            dist = [-1] * n
            dist[root] = 0
            queue, h = deque([root]), 0
            while queue:
                u = queue.popleft()
                h = max(h, dist[u])
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        queue.append(v)
            return h
        heights = [height(i) for i in range(n)]
        best = min(heights)
        return [i for i in range(n) if heights[i] == best]

