            if (k == b.length() && a.length() > b.length()) return "";
            if (k < a.length() && k < b.length()) next.get(a.charAt(k)).add(b.charAt(k));
        }
        for (char c : next.keySet()) if (!dfs(c)) return "";
        return out.reverse().toString();
    }
