    const dfs = (c) => {
        if (state.has(c)) return state.get(c) === 2;
        state.set(c, 1);
        for (const d of next.get(c)) if (!dfs(d)) return false;
        state.set(c, 2);
        out.push(c);
        return true;
    };
    for (const c of next.keys()) if (!dfs(c)) return "";
