        int[] state = new int[k + 1];
        List<Integer> post = new ArrayList<>();
        for (int v = 1; v <= k; v++) if (!dfs(v, adj, state, post)) return null;
        int[] pos = new int[k + 1];
        for (int i = 0; i < k; i++) pos[post.get(k - 1 - i)] = i;
        return pos;
    }
